//! Rational PF Riordan certificates for all rows.
//!
//! Chen--Fu--Ruan, *A unified planar network approach to total positivity of
//! combinatorial matrices and real-rootedness of polynomials*,
//! [arXiv:2512.08369v1](https://arxiv.org/abs/2512.08369v1), Theorem 3(3):
//! a lower triangular array generated by a totally nonnegative left production
//! matrix has real-rooted row polynomials. Their "totally positive" means
//! nonnegative minors. Theorem 4 identifies each finite row Toeplitz matrix
//! (transposed) as a submatrix of products of block embeddings of that left
//! production matrix, proving the stronger PF assertion, including zero rows.
//! The paragraph immediately before Theorem 3 explicitly permits arrays that
//! are not invertible, defined by product (3).
//!
//! Here `F(x,z)=d(z)/(1-x h(z))`, `h=z d K`, `d(0)>0`, with nonzero rational
//! PF series `d,K` regular at zero. Indeed
//! `Q=T(d) diag(1,T(K))` satisfies `A=Q diag(1,A)` column by column:
//! the first column is `d`, and subsequent columns are `z d K` times the
//! preceding column. Thus it generates `A[n,k]=[z^n]d h^k`, even if
//! `K(0)=0`. Toeplitz matrices of PF series are TNN; their product is TNN
//! by finite Cauchy--Binet (lower triangularity makes each sum finite).
//! Every nonzero row therefore has only real, nonpositive roots. No simplicity
//! or interlacing is asserted.
//!
//! The exact rational PF criterion is the rational specialization of Edrei,
//! *Proof of a conjecture of Schoenberg on the generating function of a totally
//! positive sequence*, Canadian J. Math. **5** (1953), 86--94,
//! [doi:10.4153/CJM-1953-010-3](https://doi.org/10.4153/CJM-1953-010-3),
//! Introduction, formula (4) and assertions A--B, pp. 86--87 (the normalized
//! case); an initial power of `z` and a positive
//! scalar restore the general case. After cancellation it is exactly
//! `c z^r prod(1+alpha z)/prod(1-beta z)`, `c>0`, `alpha,beta>=0`.
//! In the rational case the exponential and infinite products disappear.
//! The finite numerator case is the Aissen--Schoenberg--Whitney theorem,
//! *On the generating functions of totally positive sequences I*,
//! J. Analyse Math. **2** (1952), 93--103. We decide the criterion by exact
//! squarefree gcd layers, PRS root signs, and dyadic root isolation, allowing
//! real algebraic factors, arbitrary multiplicities and a zero constant of K.
//!
//! Discovery already composes this route with tails, residue classes, index
//! sections, catalog lifts and affine marker shifts. Padded reversal is tried
//! here with a certified linear degree bound and the exact generating-function
//! substitution `x^b F(1/x,x^a z)`; it preserves zero rows and nonpositive roots.

use super::*;
use crate::recurrence::generating_function::{decode_bivariate, encode_bivariate};
use crate::root_count;
use crate::Polynomial;
use ore_algebra::BivariatePolynomial as B;

const REFERENCE: &str =
    "Chen--Fu--Ruan arXiv:2512.08369v1, Theorems 3(3) and 4; rational Edrei PF criterion";

/// One monic squarefree layer of an exact polynomial factorization.
/// The original polynomial is its leading coefficient times the product of
/// these layers; a root occurs in as many layers as its multiplicity.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PolyaFrequencyRootLayer {
    /// Monic squarefree polynomial, ascending rational strings in `z`.
    pub polynomial: Vec<String>,
    /// Number of distinct negative real roots, computed by exact PRS.
    pub negative_roots: usize,
    /// Number of distinct roots at zero (zero or one).
    pub zero_roots: usize,
    /// Number of distinct positive real roots, computed by exact PRS.
    pub positive_roots: usize,
    /// Sorted dyadic isolating sets `[lower,upper]`, as rational strings.
    /// Equal endpoints mean an exact root; otherwise the endpoints are open.
    pub isolated_roots: Vec<[String; 2]>,
}

/// Exact factorization and root evidence for a nonzero rational PF series.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RationalPolyaFrequencyEvidence {
    /// Reduced series with denominator constant one.
    pub series: RationalGeneratingSeries,
    /// Whether the necessary and sufficient rational PF criterion holds.
    pub is_polya_frequency: bool,
    /// Smallest nonzero numerator power; `None` for zero (rejected here).
    pub valuation: Option<usize>,
    /// Leading numerator coefficient, an exact rational string (zero for zero).
    pub numerator_leading_coefficient: String,
    /// Monic squarefree numerator layers, with multiplicities via repetition.
    pub numerator_layers: Vec<PolyaFrequencyRootLayer>,
    /// Leading denominator coefficient, an exact rational string.
    pub denominator_leading_coefficient: String,
    /// Monic squarefree denominator layers, with multiplicities via repetition.
    pub denominator_layers: Vec<PolyaFrequencyRootLayer>,
}

fn layers(p: &[Q]) -> Vec<PolyaFrequencyRootLayer> {
    let mut p = Polynomial::new(monic(p));
    let mut result = Vec::new();
    while p.coeffs().len() > 1 {
        let gcd = p.gcd(&p.derivative());
        let layer = p.exact_div(&gcd);
        let integer = integer_coefficients(layer.coeffs());
        let signs = root_count::count_root_signs_prs_bigint_coeffs(
            &integer,
            &[BigInt::zero(), BigInt::one()],
        );
        let isolated_roots = root_count::isolate_real_roots_bigint_coeffs(&integer)
            .iter()
            .map(|r| {
                let encode = |v: &root_count::DyadicRational| {
                    Q::new(v.numerator().clone(), v.denominator()).to_string()
                };
                [encode(r.lower()), encode(r.upper())]
            })
            .collect();
        result.push(PolyaFrequencyRootLayer {
            polynomial: layer.coeffs().iter().map(ToString::to_string).collect(),
            negative_roots: signs.negative,
            zero_roots: signs.zero,
            positive_roots: signs.positive,
            isolated_roots,
        });
        p = gcd;
    }
    result
}

/// Decide the rational Edrei PF criterion exactly, after cancellation.
/// Zero is reported as rejected: this route uses nonzero PF series.
///
/// # Errors
///
/// Invalid rational coefficients or a pole at zero.
pub fn check_rational_polya_frequency(
    series: &RationalGeneratingSeries,
) -> Result<RationalPolyaFrequencyEvidence, RecurrenceError> {
    let (n, d) = series.coefficients()?;
    let series = RationalGeneratingSeries::new(&n, &d)?;
    let (n, d) = series.coefficients()?;
    let valuation = n.iter().position(|c| !c.is_zero());
    let numerator_layers = layers(&n);
    let denominator_layers = layers(&d);
    let numerator_ok = numerator_layers
        .iter()
        .all(|l| l.negative_roots + l.zero_roots == l.polynomial.len() - 1);
    let denominator_ok = denominator_layers
        .iter()
        .all(|l| l.positive_roots == l.polynomial.len() - 1);
    let positive_scalar = valuation.is_some_and(|r| n[r].is_positive());
    Ok(RationalPolyaFrequencyEvidence {
        series,
        is_polya_frequency: positive_scalar && numerator_ok && denominator_ok,
        valuation,
        numerator_leading_coefficient: n.last().cloned().unwrap_or_else(Q::zero).to_string(),
        numerator_layers,
        denominator_leading_coefficient: d.last().unwrap().to_string(),
        denominator_layers,
    })
}

/// Replayable all-index rational PF Riordan certificate.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RationalPfRiordanCertificate {
    /// Source generating function, encoding every prescribed row.
    pub generating_function: RationalGeneratingFunction,
    /// After reversal, if used; otherwise identical to `generating_function`.
    pub riordan_generating_function: RationalGeneratingFunction,
    /// Degree bound `a m+b` for row `m` relative to the first index, when reversed.
    pub reversal_degree_bound: Option<[usize; 2]>,
    /// Exact reduced `d,h,K` with `h=z d K`.
    pub decomposition: RiordanDecomposition,
    /// Exact PF factorization/root evidence for `d`.
    pub d_evidence: RationalPolyaFrequencyEvidence,
    /// Exact PF factorization/root evidence for `K`.
    pub k_evidence: RationalPolyaFrequencyEvidence,
    /// All isolated zero rows, as absolute indices before the conclusion start.
    /// Periodic zero rows are recorded in the theorem conclusion instead.
    pub finite_zero_indices: Vec<usize>,
}

impl RationalPfRiordanCertificate {
    /// Replay the generating-function identity `N E = M D`, reversal degree
    /// bound, Riordan identity and exact PF evidence, using the rule and all seeds.
    ///
    /// # Errors
    ///
    /// [`RecurrenceError::VerificationFailed`] for a changed identity or evidence;
    /// construction errors of the supplied rule are passed through.
    pub fn verify_identity(
        &self,
        rule: &Recurrence,
        first: usize,
        seeds: &[Vec<Q>],
    ) -> Result<(), RecurrenceError> {
        let gf = rational_generating_function(rule, first, seeds)?;
        let (n, d) = gf_polynomials(&gf)?;
        let (m, e) = gf_polynomials(&self.generating_function)?;
        if gf.first_index != self.generating_function.first_index
            || n.multiply(&e) != m.multiply(&d)
        {
            return Err(RecurrenceError::VerificationFailed(
                "generating-function identity N E = M D failed".into(),
            ));
        }
        let transformed = match self.reversal_degree_bound {
            None => gf,
            Some([a, b]) => reversed_gf(&gf, rule, seeds, a, b).ok_or_else(|| {
                RecurrenceError::VerificationFailed("invalid reversal degree bound".into())
            })?,
        };
        if transformed != self.riordan_generating_function
            || riordan_decomposition(&transformed).as_ref() != Some(&self.decomposition)
            || check_rational_polya_frequency(&self.decomposition.d)? != self.d_evidence
            || check_rational_polya_frequency(&self.decomposition.k)? != self.k_evidence
        {
            return Err(RecurrenceError::VerificationFailed(
                "Riordan identity or PF evidence changed".into(),
            ));
        }
        Ok(())
    }
}

fn gf_polynomials(gf: &RationalGeneratingFunction) -> Result<(B, B), RecurrenceError> {
    if gf.schema != RATIONAL_GENERATING_FUNCTION_SCHEMA {
        return Err(RecurrenceError::InvalidInput(
            "unknown generating-function schema".into(),
        ));
    }
    Ok((
        decode_bivariate(&gf.numerator)?,
        decode_bivariate(&gf.denominator)?,
    ))
}

// This is a bound for all rows by induction, not a degree fit. Only scalar
// left factors are supported for this closure; the shared GF API is broader.
fn reversal_bound(rule: &Recurrence, seeds: &[Vec<Q>], a: usize, b: usize) -> bool {
    let scalar_lhs = rule.denominator.as_ref().is_none_or(|p| {
        B::new(p.coeffs.clone())
            .as_constant()
            .is_some_and(|c| !c.is_zero())
    });
    scalar_lhs
        && rule.terms.iter().all(|t| {
            t.deriv_order == 0
                && B::new(t.coeff.coeffs.clone())
                    .variable_degree()
                    .is_none_or(|j| a.checked_mul(t.offset).is_some_and(|d| j <= d))
        })
        && seeds.iter().enumerate().all(|(m, p)| {
            a.checked_mul(m)
                .and_then(|d| d.checked_add(b))
                .is_some_and(|d| Polynomial::new(p.clone()).coeffs().len().saturating_sub(1) <= d)
        })
}

fn reversed_gf(
    gf: &RationalGeneratingFunction,
    rule: &Recurrence,
    seeds: &[Vec<Q>],
    a: usize,
    b: usize,
) -> Option<RationalGeneratingFunction> {
    if !reversal_bound(rule, seeds, a, b) {
        return None;
    }
    let substitute = |p: &B, extra: usize| -> Option<B> {
        let mut out = B::zero();
        for (i, row) in p.rows().iter().enumerate() {
            for (j, c) in row.iter().enumerate().filter(|(_, c)| !c.is_zero()) {
                let power = a.checked_mul(i)?.checked_add(extra)?.checked_sub(j)?;
                out = out.add(&B::monomial(i, power, c.clone()));
            }
        }
        Some(out)
    };
    let (n, d) = gf_polynomials(gf).ok()?;
    // The source is reduced. Substitution is an automorphism of
    // Q[x,x^-1,z], so any new common polynomial factor would be a power
    // of x. But D(x,0)=1 rules that out. Both substitutions are polynomial
    // by the induction bound, and the denominator still has D(x,0)=1.
    // Thus this pair is already reduced; a second bivariate PRS would be
    // redundant and can cause severe coefficient growth at larger slopes.
    let (n, d) = (substitute(&n, b)?, substitute(&d, 0)?);
    Some(RationalGeneratingFunction {
        schema: RATIONAL_GENERATING_FUNCTION_SCHEMA.into(),
        first_index: gf.first_index,
        numerator: encode_bivariate(&n),
        denominator: encode_bivariate(&d),
    })
}

// PF series have interval support: [valuation,degree] for polynomials,
// [valuation,infinity) otherwise. Row n is nonzero exactly when n belongs
// to the union of supports of d h^k. This computes every gap, not a scan.
fn zero_rows(
    decomposition: &RiordanDecomposition,
    first: usize,
) -> (Vec<usize>, Option<ZeroResidueClasses>) {
    let (dn, dd) = decomposition.d.coefficients().unwrap();
    if dd.len() > 1 {
        return (Vec::new(), None);
    }
    let (hn, hd) = decomposition.h.coefficients().unwrap();
    let s = hn.iter().position(|c| !c.is_zero()).unwrap();
    let upper_d = dn.len() - 1;
    if hd.len() > 1 {
        return (((upper_d + 1)..s).map(|m| first + m).collect(), None);
    }
    let upper_h = hn.len() - 1;
    if s == upper_h {
        let mut residues: Vec<usize> = ((upper_d + 1)..s).map(|m| (first + m) % s).collect();
        residues.sort_unstable();
        return (
            Vec::new(),
            (!residues.is_empty()).then_some(ZeroResidueClasses {
                period: s,
                residues,
            }),
        );
    }
    let mut gaps = Vec::new();
    let mut k = 0;
    while k * (upper_h - s) + upper_d + 1 < s {
        gaps.extend(((k * upper_h + upper_d + 1)..((k + 1) * s)).map(|m| first + m));
        k += 1;
    }
    (gaps, None)
}

/// Prove all nonzero rows real-rooted with nonpositive zeros by rational PF
/// Riordan recognition (module documentation), also trying padded reversals.
///
/// # Errors
///
/// Malformed rational data or a failure of exact arithmetic/normalization.
pub fn check_rational_pf_riordan_theorem(
    rule: &Recurrence,
    first_index: usize,
    seeds: &[Vec<Q>],
    options: &RealRootednessTheoremOptions,
) -> Result<RealRootednessTheoremReport, RecurrenceError> {
    check_with_first_proving_start(
        RealRootednessTheorem::RationalPfRiordan,
        rule,
        first_index,
        seeds,
        options,
    )
}

pub(super) const ROUTE: TheoremRoute = TheoremRoute {
    theorem: RealRootednessTheorem::RationalPfRiordan,
    check_at_supplied_seeds: rational_pf_riordan_report,
    start_policy: StartPolicy::MovesStart,
    is_preferred: any_proof,
    certificate_name: Some("rational PF Riordan"),
    discovery: DiscoveryPolicy::WhenApplicable,
    in_residue_class_menu: true,
    in_index_section_menu: true,
    parent: ParentPolicy {
        stage: ParentStage::WhileUnproved,
        region: ParentRegion::Unrestricted,
        record_only_if_applicable: true,
    },
};

pub(super) fn verify_certificate_in_report(
    certificate: &RationalPfRiordanCertificate,
    report: &RealRootednessTheoremReport,
) -> Result<(), RecurrenceError> {
    let (rule, first, seeds) = report.recurrence.to_recurrence_parts()?;
    let rows = rule
        .generate_rows_rational(&seeds, first, seeds.len() + report.start_delay)
        .map_err(|e| RecurrenceError::VerificationFailed(e.to_string()))?;
    let (rule, _) = rule_with_x_free_left_hand_factor(&rule)?;
    certificate.verify_identity(&rule, first, &rows)
}

fn rational_pf_riordan_report(
    rule: &Recurrence,
    first: usize,
    seeds: &[Vec<Q>],
    options: &RealRootednessTheoremOptions,
) -> Result<RealRootednessTheoremReport, RecurrenceError> {
    let mut report = RealRootednessTheoremReport::new(
        RealRootednessTheorem::RationalPfRiordan,
        REFERENCE,
        rule,
        first,
        seeds,
        options,
    );
    let gf = match rational_generating_function(rule, first, seeds) {
        Ok(gf) => gf,
        Err(RecurrenceError::Unsupported(reason) | RecurrenceError::InvalidInput(reason)) => {
            return Ok(report.not_applicable(reason))
        }
        Err(e) => return Err(e),
    };
    let mut candidates = vec![(gf.clone(), None)];
    for a in 1usize..=3 {
        let b = seeds
            .iter()
            .enumerate()
            .map(|(m, p)| {
                Polynomial::new(p.clone())
                    .coeffs()
                    .len()
                    .saturating_sub(1)
                    .saturating_sub(a * m)
            })
            .max()
            .unwrap_or(0);
        if let Some(reversed) = reversed_gf(&gf, rule, seeds, a, b) {
            candidates.push((reversed, Some([a, b])));
        }
    }
    let mut first_failure = None;
    for (candidate, reversal) in candidates {
        // These candidates were constructed reduced. Reject their shape
        // before invoking the public recognizer, which also accepts and
        // reduces noncanonical caller-supplied pairs.
        let (n, d) = gf_polynomials(&candidate)?;
        if !n.is_variable_free() || d.variable_degree().is_none_or(|degree| degree > 1) {
            continue;
        }
        let Some(decomposition) = riordan_decomposition(&candidate) else {
            continue;
        };
        let d_evidence = check_rational_polya_frequency(&decomposition.d)?;
        let k_evidence = check_rational_polya_frequency(&decomposition.k)?;
        let positive_d0 = d_evidence.valuation == Some(0);
        let pf = positive_d0 && d_evidence.is_polya_frequency && k_evidence.is_polya_frequency;
        let evidence = format!(
            "d = {}; K = {}; d(0)>0 and PF: {}; K PF: {}",
            decomposition.d,
            decomposition.k,
            positive_d0 && d_evidence.is_polya_frequency,
            k_evidence.is_polya_frequency
        );
        if !pf {
            first_failure.get_or_insert(evidence);
            continue;
        }
        let (finite_zero_indices, zero_residue_classes) = zero_rows(&decomposition, first);
        let conclusion_first = finite_zero_indices.last().map_or(first, |n| n + 1);
        report.normal_form =
            format!("F = d/(1-x z d K); {evidence}; reversal degree bound {reversal:?}");
        report.hypotheses.push(exact_hypothesis(
            "rational_pf_factors",
            "the exact generating function (including every seed) is Riordan with \
             d(0)>0 and nonzero rational PF d,K",
            Ok(evidence),
        ));
        if let Some(region) = &options.root_region {
            let contains =
                region.lower.is_none() && region.upper.as_ref().is_none_or(Signed::is_positive);
            report.hypotheses.push(if contains {
                exact_hypothesis(
                    "requested_root_region",
                    "the requested region contains (-inf,0]",
                    Ok("exact endpoint comparison".into()),
                )
            } else {
                unresolved_hypothesis(
                    "requested_root_region",
                    "the requested region contains (-inf,0]",
                    "this theorem certifies only the closed nonpositive ray".into(),
                )
            });
        }
        let zero_text = format!(
            "isolated zero indices {finite_zero_indices:?}; \
             periodic zero classes {zero_residue_classes:?}"
        );
        report.certificate = Some(RouteCertificate::RationalPfRiordan(Box::new(
            RationalPfRiordanCertificate {
                generating_function: gf,
                riordan_generating_function: candidate,
                reversal_degree_bound: reversal,
                decomposition,
                d_evidence,
                k_evidence,
                finite_zero_indices,
            },
        )));
        return Ok(report.finish(RealRootednessTheoremConclusion {
            first_index: conclusion_first,
            zero_residue_classes,
            interlacing_from: None,
            interlacing: None,
            simple_roots: false,
            root_region: Some(RootInterval::from_real(&RealInterval {
                lower: None,
                lower_closed: false,
                upper: Some(Q::zero()),
                upper_closed: true,
            })),
            statement: format!(
                "every nonzero P_n, n >= {first}, has only real nonpositive zeros; \
                 {zero_text}; no simplicity or interlacing asserted"
            ),
        }));
    }
    if let Some(evidence) = first_failure {
        report.normal_form = "Riordan shape, but rational PF hypotheses fail".into();
        report.hypotheses.push(exact_hypothesis(
            "rational_pf_factors",
            "d(0)>0 and d,K are nonzero rational PF series",
            Err((None, evidence)),
        ));
        report.status = RealRootednessTheoremStatus::HypothesisFailed;
        Ok(report)
    } else {
        Ok(report.not_applicable(
            "no reduced Riordan generating function, directly or after a certified reversal",
        ))
    }
}
